import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import AOS from "aos";
import "aos/dist/aos.css";

export default function ADIDroneHomePage() {
  const navigate = useNavigate();

  useEffect(() => {
    AOS.init({ duration: 800, once: true });
  }, []);

  const [counts, setCounts] = useState({ fires: 0, alerts: 0, injured: 0 });

  useEffect(() => {
    const animate = (key, target, delay = 0) => {
      let current = 0;
      const step = () => {
        if (current < target) {
          current++;
          setCounts((prev) => ({ ...prev, [key]: current }));
          setTimeout(step, delay);
        }
      };
      step();
    };
    animate("fires", 5);
    animate("alerts", 34);
    animate("injured", 12);
  }, []);

  return (
    <div className="min-h-screen bg-black text-white font-sans">
      {/* Hero Section */}
      <section className="text-center py-20 px-6">
        <h1 className="text-5xl font-bold text-cyan-400 mb-2" data-aos="fade-up">
          ADI – THE THIRD EYE
        </h1>
        <p className="text-xl text-cyan-200 mb-6 uppercase tracking-wide" data-aos="fade-up">
          Vision of the Future
        </p>
        <p className="max-w-2xl mx-auto text-gray-300 mb-8" data-aos="zoom-in">
          AI-Powered Quadcopter for Crowd Control, Disaster Response, and Surveillance in India.
        </p>
        <div className="flex justify-center gap-4" data-aos="zoom-in-up">
          <button
            onClick={() => navigate("/live-demo")}
            className="bg-cyan-500 hover:bg-cyan-600 text-white px-6 py-2 rounded-xl shadow-lg transition-all"
          >
            LIVE DEMO
          </button>
          <button
            onClick={() => navigate("/project")}
            className="bg-gray-800 border border-cyan-500 px-6 py-2 rounded-xl hover:bg-cyan-900 transition-all"
          >
            VIEW PROJECT
          </button>
        </div>
      </section>

      {/* Feature Grid */}
      <section className="grid grid-cols-1 md:grid-cols-4 gap-6 px-6 py-12 text-center">
        {[
          ["Real-time Crowd Monitoring", "Heat-mapping", "/features/crowd"],
          ["Thermal Vision", "Fire Alerts", "/features/thermal"],
          ["Panic Detection", "(BlazePose)", "/features/panic"],
          ["Night Vision", "Low Light Enhancement", "/features/night"],
        ].map(([title, desc, link], i) => (
          <div
            key={i}
            data-aos="flip-left"
            onClick={() => navigate(link)}
            className="bg-gray-800 p-4 rounded-2xl hover:scale-105 transition-transform shadow-lg cursor-pointer"
          >
            <h3 className="text-lg font-semibold text-cyan-300 mb-1">{title}</h3>
            <p className="text-sm text-gray-400">{desc}</p>
          </div>
        ))}
      </section>

      {/* Feed Preview Grid */}
      <section className="grid grid-cols-2 md:grid-cols-4 gap-4 px-6 pb-12" data-aos="fade-up">
        {["RGB Feed", "Thermal View", "Depth Map", "GPS Map"].map((label, i) => (
          <div
            key={i}
            className="aspect-video bg-gray-900 rounded-xl flex items-center justify-center text-sm text-gray-400 hover:shadow-lg hover:shadow-cyan-500/10 transition-all"
          >
            {label}
          </div>
        ))}
      </section>

      {/* Stats Section */}
      <section className="text-center pb-12" data-aos="fade-in">
        <h2 className="text-2xl text-cyan-400 mb-6">Live Stats</h2>
        <div className="flex justify-center gap-12 text-lg text-gray-300">
          <div>
            <span className="text-cyan-300 text-3xl block">{counts.fires}</span>
            Fires
          </div>
          <div>
            <span className="text-cyan-300 text-3xl block">{counts.alerts}</span>
            Crowd Alerts
          </div>
          <div>
            <span className="text-cyan-300 text-3xl block">{counts.injured}</span>
            Injured Detected
          </div>
        </div>
      </section>

      {/* Tech Stack */}
      <section className="py-10 px-6" data-aos="zoom-in">
        <div className="flex flex-wrap justify-center gap-6">
          {["YOLOv8", "BlazePose", "MediaPipe", "Raspberry Pi", "Mapbox", "WhisperX", "ThermalSim", "Zero-DCE++"].map(
            (tech, i) => (
              <span
                key={i}
                className="bg-gray-800 text-cyan-200 px-4 py-2 rounded-full text-sm shadow"
              >
                {tech}
              </span>
            )
          )}
        </div>
      </section>

      {/* Contact Section */}
      <section className="text-center py-12 px-6" data-aos="fade-up">
        <p className="text-gray-400">Prachi ma'am | erachi@example.com</p>
        <a
          href="/ADI-Drone-Report.pdf"
          download
          className="mt-4 inline-block bg-cyan-500 px-6 py-2 rounded-xl hover:bg-cyan-600 transition-all"
        >
          📥 Download Report
        </a>
      </section>
    </div>
  );
}
